css:
.sl-cta-floating {
    padding-block: clamp(4.5rem, 9vw, 8rem);
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-cta-floating .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-cta-floating .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-cta-floating.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-cta-floating .sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-cta-floating .sl-float-card {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-card-bg) 82%, transparent);
}
.sl-cta-floating .sl-float-badge {
    background-color: var(--smartlearn-card-bg);
}
.sl-cta-floating .sl-backdrop-blur {
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}
.sl-cta-floating .sl-cta-btn-label { letter-spacing: 0.05em; }
.sl-cta-floating .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg) !important;
    border-color: var(--smartlearn-btn-bg) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
}
.sl-cta-floating .sl-btn-primary:hover,
.sl-cta-floating .sl-btn-primary:focus-visible {
    transform: translateY(-3px);
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2) !important;
}
.sl-cta-floating .sl-btn-primary:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@keyframes sl-cta-floating-y {
    0% { transform: translateY(0); }
    50% { transform: translateY(-20px); }
    100% { transform: translateY(0); }
}
.sl-cta-floating .sl-float-item { animation: sl-cta-floating-y 6s ease-in-out infinite; }
.sl-cta-floating .sl-float-1 { width: 60px; height: 60px; top: 15%; inset-inline-start: 10%; animation-delay: 0s; }
.sl-cta-floating .sl-float-2 { width: 80px; height: 80px; bottom: 20%; inset-inline-start: 6%; animation-delay: 1.5s; }
.sl-cta-floating .sl-float-3 { width: 70px; height: 70px; top: 25%; inset-inline-end: 8%; animation-delay: 0.5s; }
.sl-cta-floating .sl-float-4 { bottom: 28%; inset-inline-end: 10%; animation-delay: 2s; }
.sl-cta-floating .sl-float-5 { top: 10%; inset-inline-end: 24%; animation-delay: 1s; }
@media (prefers-reduced-motion: reduce) {
    .sl-cta-floating .sl-float-item { animation: none; }
    .sl-cta-floating .sl-btn-primary { transition: none; }
    .sl-cta-floating .sl-btn-primary:hover,
    .sl-cta-floating .sl-btn-primary:focus-visible { transform: none; }
}
@media (max-width: 767.98px) {
    .sl-cta-floating .sl-floating-container { display: none; }
    .sl-cta-floating .sl-float-card {
        padding: 2rem;
        border: none;
        background-color: transparent;
        box-shadow: none;
        backdrop-filter: none;
    }
}
